// NB ADR 0048: generated by pnpm site:generate from docs/self-host.md; never edit by hand

export const SELF_HOST_HTML: string =
  '<h1 id="self-host-todz">Self-host todz</h1>\n<p>Run your own todz server on Cloudflare and point the macOS app and your agents at it. The server is one Worker with a D1 database and one Durable Object per project (ADR 0044).</p>\n<h2 id="what-you-need">What you need</h2>\n<ul>\n<li>A Cloudflare account on <strong>Workers Paid</strong> (the email binding needs it) and a domain in that account. Below, <code>example.com</code> stands for it and <code>api.example.com</code> for the server.</li>\n<li>Node and pnpm, in the versions of <code>.nvmrc</code> and <code>package.json</code>, and a Mac with Xcode and XcodeGen for the app.</li>\n<li>Wrangler logged in to your account: <code>pnpm --filter @todz/api exec wrangler login</code>.</li>\n</ul>\n<h2 id="1-fork-install-and-check">1. Fork, install and check</h2>\n<p>Fork the repository, then, before renaming anything:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm install\npnpm verify all</code></pre>\n<p>The gate also needs gitleaks; its doctor names anything missing. Run it now, because some tests pin todz&#39;s own production names, for example <code>tools/repository-shape/src/api-source.test.ts</code> and <code>apps/api/test/email-sender.test.ts</code>. After step 2 those pins fail until you update them to your names.</p>\n<h2 id="2-rename">2. Rename</h2>\n<p>Edit <code>apps/api/wrangler.jsonc</code>:</p>\n<ul>\n<li><code>account_id</code>: your account&#39;s id.</li>\n<li><code>routes</code>: replace <code>api.todz.app</code>, <code>todz.app</code> and <code>www.todz.app</code> with <code>api.example.com</code>, <code>example.com</code> and <code>www.example.com</code>, keeping <code>custom_domain</code> <code>true</code>.</li>\n<li><code>vars.PUBLIC_ORIGIN</code>: <code>https://api.example.com</code>.</li>\n<li><code>vars.SITE_ORIGIN</code>: <code>https://example.com</code>, where the landing page and this guide are served.</li>\n<li><code>send_email[0].allowed_sender_addresses</code>: your sender, for example <code>noreply@example.com</code>.</li>\n<li><code>ratelimits</code>: keep the three bindings; change each <code>namespace_id</code> if your account already uses <code>8601</code> to <code>8603</code>.</li>\n</ul>\n<p>Keep the rest as it is. In particular, <code>vars.SIGN_IN_PROVIDER</code> stays <code>email</code>, <code>vars.EMAIL_SENDER</code> stays <code>cloudflare</code>, and <code>workers_dev</code> and <code>preview_urls</code> stay <code>false</code>. Never pass <code>--var</code> to <code>wrangler deploy</code>, and never set variables in the dashboard: a fake provider, or a sender that only logs the link, opens sign-in to anyone.</p>\n<p>In <code>apps/api/src/email-sender.ts</code>, set <code>SENDER_ADDRESS</code> and <code>REPLY_TO_ADDRESS</code> to your own addresses.</p>\n<h2 id="3-create-the-database-and-apply-the-migrations">3. Create the database and apply the migrations</h2>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler d1 create todz-directory</code></pre>\n<p>Put the printed id in <code>d1_databases[0].database_id</code>, then:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler d1 migrations apply todz-directory --remote</code></pre>\n<h2 id="4-deploy">4. Deploy</h2>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler deploy</code></pre>\n<p>Cloudflare creates the DNS records and the certificates for <code>api.example.com</code>, <code>example.com</code> and <code>www.example.com</code>; none of the three may already have an A, AAAA or CNAME record. Check three things:</p>\n<ul>\n<li><code>curl -sS https://api.example.com/owner/sign-in-method</code> answers <code>{&quot;method&quot;:&quot;link&quot;}</code>;</li>\n<li>the account&#39;s <code>todz-api.&lt;subdomain&gt;.workers.dev</code> address does not answer;</li>\n<li>until step 6 is done, sending a link answers 503 <code>sign_in_unavailable</code>, which is the safe state.</li>\n</ul>\n<h2 id="5-email-sending">5. Email sending</h2>\n<p>Enable sending for your domain and add the records Cloudflare lists. The zone id is on the domain&#39;s Overview page in the dashboard.</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler email sending enable example.com --zone-id &lt;your zone id&gt;\npnpm --filter @todz/api exec wrangler email sending dns get example.com --zone-id &lt;your zone id&gt;</code></pre>\n<h2 id="6-turnstile">6. Turnstile</h2>\n<p>Sign-in stays closed (<code>sign_in_unavailable</code>) until Turnstile is set up (ADR 0045). In the Cloudflare dashboard, create a Turnstile widget for <code>example.com</code> in Managed mode. Put its site key in <code>vars.TURNSTILE_SITE_KEY</code> in <code>apps/api/wrangler.jsonc</code>, deploy again, and store its secret:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler secret put TURNSTILE_SECRET_KEY</code></pre>\n<p>Wrangler asks for the value, which keeps it out of your shell history. Never pipe it in, never export it, and never write it into <code>wrangler.jsonc</code>.</p>\n<h2 id="7-point-the-macos-app-at-your-server">7. Point the macOS app at your server</h2>\n<p>In <code>apps/macos/project.yml</code>:</p>\n<ul>\n<li>set the <code>TODZ_API_BASE_URL</code> build setting for the Release configuration to <code>https://api.example.com</code>;</li>\n<li>in both targets, replace <code>DEVELOPMENT_TEAM</code> with your own team&#39;s id (Xcode → Settings → Accounts; the free Personal Team works);</li>\n<li>replace <code>bundleIdPrefix</code>, the <code>TODZ_APP_BUNDLE_IDENTIFIER</code> and <code>TODZ_WIDGETS_BUNDLE_IDENTIFIER</code> values and <code>TODZ_APP_GROUP</code> with identifiers of your own.</li>\n</ul>\n<p>Then build:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>xcodegen generate --spec apps/macos/project.yml\nxcodebuild build -project apps/macos/Todz.xcodeproj -scheme Todz -configuration Release -derivedDataPath apps/macos/build</code></pre>\n<p>Sign in with your email, then open <strong>Connect an agent</strong> in the sidebar.</p>\n<h2 id="8-point-an-mcp-client-at-your-server">8. Point an MCP client at your server</h2>\n<p><strong>Connect an agent</strong> shows a ready command with your server and a new key. For Claude Code it has this shape:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>claude mcp add --transport http todz &#39;https://api.example.com/mcp&#39; --header &#39;Authorization: Bearer &lt;key&gt;&#39;</code></pre>\n<p>A key belongs to one project, and the server reads the project from it (<code>docs/product</code>). The command puts the key in your shell history. Run it with a leading space if your shell skips those, or use the Cursor form, which keeps the key in its JSON configuration.</p>\n<h2 id="updating">Updating</h2>\n<p>Pull from upstream, then run:</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler d1 migrations apply todz-directory --remote\npnpm --filter @todz/api exec wrangler deploy</code></pre>\n<p>Migrations only move forward. Never roll back to a version from before the sign-in guard, whether with <code>wrangler rollback</code> or the dashboard&#39;s Deployments page. To close sign-in, delete the secret (the runbook):</p>\n<pre class="code" tabindex="0" role="region" aria-label="Code"><code>pnpm --filter @todz/api exec wrangler secret delete TURNSTILE_SECRET_KEY</code></pre>';
